import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1792658569000}`),a={name:`changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to “更新日志”">​</a></h1><p>本页记录 <code>@xihan-report/core</code>、<code>@xihan-report/runtime</code>、<code>@xihan-report/designer</code> 各版本使用者能感知的变更，每条标注 <strong>新增 / 修复 / 调整 / 移除</strong>。这几个包总是同一个版本号一起发布；逐包的完整记录见仓库里各包的 <code>CHANGELOG.md</code>。</p><h2 id="v1-0-0-rc-2-2026-10-22" tabindex="-1">v1.0.0-rc.2（2026-10-22） <a class="header-anchor" href="#v1-0-0-rc-2-2026-10-22" aria-label="Permalink to “v1.0.0-rc.2（2026-10-22）”">​</a></h2><ul><li><strong>新增</strong> <code>@xihan-report/designer</code>：<code>&lt;xh-report-designer&gt;</code> 的 <code>closable</code> 属性（同名 attribute）。开着时菜单栏最右端显示关闭钮，按下派发 <code>close</code>，由宿主关掉设计器或回到列表，有未保存的改动时先问。</li><li><strong>修复</strong> <code>@xihan-report/designer</code>：选中工具条上的钮（副本、复制、删除与扩展登记的命令）用指针按下时不再清掉选中，命令照常执行。</li><li><strong>修复</strong> <code>@xihan-report/designer</code>：卡片在不动的指针下挪走（拖动松手、方向键挪动、撤销与重做）后，画布上不再留下悬停框。</li><li><strong>修复</strong> <code>@xihan-report/runtime</code>：简体与繁体中文的历史记录里，步骤名中的数目与前后的汉字之间加上空格，如「调整 7 个卡片的布局」。</li><li><strong>调整</strong> <code>@xihan-report/designer</code>：移动卡片与改卡片大小更流畅，手势途中只重画画布、选中框与状态栏，面板在松手后更新一次。</li><li><strong>调整</strong> 三个包对 <code>@xihan-ui/*</code> 的 peer 依赖提到 <code>^5.1.0</code>，项目里的 XiHan.UI 需要升到 5.1.0 或更高。</li></ul><h2 id="v1-0-0-rc-1-2026-10-21" tabindex="-1">v1.0.0-rc.1（2026-10-21） <a class="header-anchor" href="#v1-0-0-rc-1-2026-10-21" aria-label="Permalink to “v1.0.0-rc.1（2026-10-21）”">​</a></h2><p>首次发布，以原生 Web Components 交付，不绑定前端框架。报表定义是纯 JSON，按数据集与参数取数后在浏览器里算出明细表、分组报表、交叉表与看板，看板的卡片能联动、表格能下钻，结果能导出 Excel。</p><ul><li><strong>新增</strong> <code>@xihan-report/core</code>：报表定义的结构（数据集与字段、计算字段、报表参数，主体是明细表、分组报表、交叉表或看板与卡片，卡片之间的联动）、校验与问题码、按参数与联动选中算出取数请求、按取回的明细行或汇总行计算视图与卡片（聚合、透视、排序、公式度量）、编辑操作与撤销重做、卡片与视图种类的登记与扩展合并。纯 TypeScript，不依赖 DOM。</li><li><strong>新增</strong> <code>@xihan-report/runtime</code>：<code>&lt;xh-report-viewer&gt;</code> 按报表定义与取数回调计算并显示明细表、分组报表、交叉表与看板，带参数栏、卡片联动与表格下钻事件；<code>export(&#39;xlsx&#39;)</code> 把当前的计算结果写成 Excel 工作簿，<code>@xihan-report/runtime/xlsx</code> 把视图排成工作表；与 XiHan.UI 内建语言一一对应的界面语言包（<code>@xihan-report/runtime/locale</code>），查看器与设计器共用。</li><li><strong>新增</strong> <code>@xihan-report/designer</code>：<code>&lt;xh-report-designer&gt;</code> 可视化设计器，包括菜单栏与工具栏、数据集与报表参数面板、物料、看板卡片的拖动与改大小、画布缩放、字段栏、属性面板、问题列表、预览、撤销重做与剪贴板，页面结构与历史记录面板，设置对话框（主题、主题色、语言、布局、工具栏、自动保存与开发者模式），从 JSON 样例或 JSON Schema 导入数据集、字段与参数，按 JSON 编辑整份报表，按 <code>draftKey</code> 在本机自动保存的草稿，以及新手引导。卡片与视图种类、渲染、导出器、取数中间件、属性编辑器、命令、面板、物料、物料来源、导入器、菜单栏的菜单与设置分区都能经 <code>extensions</code> 登记。</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};